-- Add recipe provenance tracking (launch-readiness).
--
-- source records where a SHARED seed recipe (household_id IS NULL) came from,
-- so copyright-sensitive content can be found, audited and replaced later
-- without guessing. Household-owned recipes keep source NULL (user content).
--
--   'ica.se'         the 110 recipes in 012_seed_100_recipes.sql, generated by
--                    tools/scrape_ica_recipes.py from ICA.se. Third-party
--                    content: see docs/recipe-provenance.md for the
--                    replacement plan.
--   'maltiden-seed'  the 20 hand-written seed recipes in 004 and 008.
--
-- Additive and non-destructive: one nullable column plus UPDATEs scoped by
-- explicit id AND household_id IS NULL, so no user recipe is touched.
ALTER TABLE recipes ADD COLUMN source TEXT;

UPDATE recipes SET source = 'maltiden-seed'
WHERE household_id IS NULL AND id IN (
